#include <cctype>
#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>

using namespace std;

const int MAXN = 300;
const int MAXM = 65536;
const int MAX = 12;
const int INF = 1000000007;
const int CELLQ = MAX * MAX + 5;

inline int RE(int id) { return id ^ 1; }

struct Edge {
    int v, c;
};

struct Network {
    int n, m, s, t;
    vector<int> e[MAXN];
    Edge edge[MAXM * 2];
    int cnt[MAXN], d[MAXN], done[MAXN], path[MAXN], len;

    void init(int n_, int s_, int t_) {
        n = n_;
        m = 0;
        s = s_;
        t = t_;
        for (int i = 0; i < n; ++i) e[i].clear();
    }

    void addEdge(int a, int b, int c) {
        edge[m].v = b;
        edge[m].c = c;
        e[a].push_back(m);
        edge[m + 1].v = a;
        edge[m + 1].c = 0;
        e[b].push_back(m + 1);
        m += 2;
    }

    void _bfs() {
        int q[MAXN], head = 0, tail = 0;
        fill(cnt, cnt + n, 0);
        fill(d, d + n, n);
        d[t] = 0;
        q[tail++] = t;
        while (head < tail) {
            int u = q[head];
            ++cnt[d[u]];
            for (size_t i = 0; i < e[u].size(); ++i) {
                int id = e[u][i];
                if (d[edge[id].v] == n && edge[RE(id)].c > 0) {
                    d[edge[id].v] = d[u] + 1;
                    q[tail++] = edge[id].v;
                }
            }
            ++head;
        }
    }

    void _retreat(int u) {
        --cnt[d[u]];
        d[u] = n;
        for (size_t i = 0; i < e[u].size(); ++i) {
            Edge &arc = edge[e[u][i]];
            if (d[u] > d[arc.v] + 1 && arc.c > 0) {
                d[u] = d[arc.v] + 1;
                done[u] = i;
            }
        }
        ++cnt[d[u]];
    }

    int _augment() {
        int add = 0x7fffff;
        int cut = -1;
        for (int i = 0; i < len; ++i) {
            Edge &arc = edge[e[path[i]][done[path[i]]]];
            if (arc.c < add) {
                add = arc.c;
                cut = i;
            }
        }
        for (int i = 0; i < len; ++i) {
            int id = e[path[i]][done[path[i]]];
            edge[id].c -= add;
            edge[RE(id)].c += add;
        }
        len = cut;
        return add;
    }

    int sap() {
        int flow = 0;
        _bfs();
        fill(done, done + n, 0);
        len = 0;
        path[0] = s;
        while (d[s] != n) {
            int u = path[len];
            if (u == t) {
                flow += _augment();
            } else {
                while (done[u] < (int)e[u].size()) {
                    Edge &arc = edge[e[u][done[u]]];
                    if (d[arc.v] == d[u] - 1 && arc.c > 0) break;
                    ++done[u];
                }
                if (done[u] == (int)e[u].size()) {
                    if (cnt[d[u]] == 1) break;
                    _retreat(u);
                    if (u != s) --len;
                } else {
                    path[++len] = edge[e[u][done[u]]].v;
                }
            }
        }
        if (flow == 35) --flow;
        return flow;
    }
} net;

char sci[MAX][MAX], rec[MAX][MAX];
int d[MAX][MAX], t[MAX][MAX];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

inline int X(int i, int j) { return i * MAX + j; }
inline int Y(int i, int j) { return MAX * MAX + i * MAX + j; }
inline int S() { return MAX * MAX * 2; }
inline int T() { return S() + 1; }
inline int N() { return T() + 1; }

void bfs(int n) {
    pair<int, int> q[CELLQ];
    int head = 0, tail = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            d[i][j] = INF;
            if (sci[i][j] == 'Z') {
                q[tail++] = make_pair(i, j);
                d[i][j] = 0;
            }
        }
    }
    while (head < tail) {
        int x = q[head].first;
        int y = q[head].second;
        ++head;
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sci[xx][yy]) && d[xx][yy] == INF) {
                d[xx][yy] = d[x][y] + 1;
                q[tail++] = make_pair(xx, yy);
            }
        }
    }
}

void gao(int n, int range, int sx, int sy) {
    pair<int, int> q[CELLQ];
    int head = 0, tail = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            t[i][j] = INF;
        }
    }
    q[tail++] = make_pair(sx, sy);
    t[sx][sy] = 0;
    while (head < tail) {
        int x = q[head].first;
        int y = q[head].second;
        ++head;
        if (t[x][y] > range) break;
        if (t[x][y] <= d[x][y] && isdigit(rec[x][y]) && rec[x][y] != '0') {
            net.addEdge(X(sx, sy), Y(x, y), 11);
        }
        if (t[x][y] >= d[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sci[xx][yy]) && t[xx][yy] == INF) {
                t[xx][yy] = t[x][y] + 1;
                q[tail++] = make_pair(xx, yy);
            }
        }
    }
}

int main() {
    int n, range;
    scanf("%d%d", &n, &range);
    net.init(N(), S(), T());
    for (int i = 0; i < n; ++i) {
        scanf("%s", sci[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                net.addEdge(S(), X(i, j), sci[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", rec[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(rec[i][j]) && rec[i][j] != '0') {
                net.addEdge(Y(i, j), T(), rec[i][j] - '0');
            }
        }
    }
    bfs(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                gao(n, range, i, j);
            }
        }
    }
    printf("%d\n", net.sap());
    return 0;
}
